'use client';
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { avatarInk, enter, Fold, Tip } from '../lib/motion';
import { hoverGlide } from '../lib/glide';
import '../designme.css';
import './source-stack.css';

export interface StackSource {
  /** What kind of source it is. The filter chips pick by this, like 'web', 'file' or 'figma' */
  kind: string;
  title: string;
  /** Where it came from, like "baymard.com" or "Drive" */
  host: string;
  /** 0 to 1, drawn as a small bar */
  relevance: number;
  /** One to three letters in the favicon square, like "B" or "CSV" */
  mark: string;
  /** The favicon's fill: a colour dark enough for white letters, like '#635bff', or an avatar colour like 'var(--dm-av-l)',
      which brings its own ink. Clean draws every mark in its neutral grey */
  color: string;
  /** Adds an open button that shows on hover */
  onOpen?: () => void;
}

export interface SourceFilter {
  /** 'all', or a source kind */
  value: string;
  label: string;
}

export interface SourceStackProps {
  /** The answer the sources back up, shown above the pill */
  children?: ReactNode;
  sources: StackSource[];
  /** The chips above the list. Defaults to All, Web, Files and Figma */
  filters?: SourceFilter[];
  /** The chosen filter. Leave it out to let the chips switch it */
  filter?: string;
  defaultFilter?: string;
  onFilterChange?: (filter: string) => void;
  /** Whether the list is open. Leave it out to let the pill toggle it */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

const FILTERS: SourceFilter[] = [{ value: 'all', label: 'All' }, { value: 'web', label: 'Web' }, { value: 'file', label: 'Files' }, { value: 'figma', label: 'Figma' }];

/** An answer with its sources stacked in a pill. Open it to see each source, filter them, and how much each one counted. */
export function SourceStack({ children, sources, filters = FILTERS, filter, defaultFilter = 'all', onFilterChange, open, defaultOpen = false, onOpenChange, className }: SourceStackProps) {
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const [f, setF] = useControllable(filter, defaultFilter, onFilterChange);
  // the list staggers in again each time it opens
  const [opened, setOpened] = useState(0);
  const [wasOpen, setWasOpen] = useState(isOpen);
  if (isOpen !== wasOpen) { setWasOpen(isOpen); if (isOpen) setOpened(n => n + 1); }
  const items = sources.filter(s => f === 'all' || s.kind === f);
  // Clean's one hover glides from source to source (the list is drawn afresh as it opens or its filter changes)
  const listRef = useRef<HTMLDivElement>(null);
  useEffect(() => hoverGlide(listRef.current, '.dm-ssx-s'), [f, opened]);

  return (
    <div data-dm="" className={cx('dm-ssx', className)}>
      {children !== undefined && <p className="dm-msg">{children}</p>}
      <button type="button" className="dm-ssx-pill" aria-expanded={isOpen} onClick={() => setOpen(!isOpen)}>
        <span className="dm-ssx-ics">{sources.slice(0, 4).map((s, i) => <span key={i} style={{ background: s.color, color: avatarInk(s.color) }}>{s.mark[0]}</span>)}</span>
        <span className="dm-ssx-l">{sources.length} {sources.length === 1 ? 'source' : 'sources'}</span>
        <Icon name="chev-d" size="xs" />
      </button>
      <Fold open={isOpen} className="dm-ssx-box">
        <div className="dm-ssx-in">
          <div className="dm-ssx-fl">
            {filters.map(x => <button key={x.value} type="button" className={cx('dm-chip dm-sm', x.value === f && 'dm-on')} aria-pressed={x.value === f} onClick={() => setF(x.value)}>{x.label}</button>)}
          </div>
          <div ref={listRef} className="dm-ssx-list" key={f + ':' + opened}>
            {items.map((s, i) => {
              const e = enter(i * 40), pct = Math.round(Math.max(0, Math.min(1, s.relevance)) * 100);
              return (
                <div key={s.title + i} className={cx('dm-ssx-s', e.className)} style={e.style}>
                  <span className="dm-fv" style={{ background: s.color, color: avatarInk(s.color) }}>{s.mark}</span>
                  <span className="dm-t"><span>{s.title}</span><span className="dm-h"> · {s.host}</span></span>
                  <Tip label={`Relevance ${pct}%`}><span className="dm-rel" role="meter" aria-label="Relevance" aria-valuemin={0} aria-valuemax={100} aria-valuenow={pct}><i style={{ width: pct + '%' }} /></span></Tip>
                  {s.onOpen && <Tip label="Open"><button type="button" className="dm-ib" aria-label="Open source" onClick={s.onOpen}><Icon name="ext" size="xs" /></button></Tip>}
                </div>
              );
            })}
          </div>
        </div>
      </Fold>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Source stack ---------- */
/* everything the agent read, folded into one pill under the answer: the first sources' marks side by side (never stacked
   over each other, owner, 18 Nov) and the count. Open, a filter and the list: each source's mark, its title and where it
   came from, how much it counted, and a button to open it. A mark is a vivid fill of its own with white letters (or an
   avatar colour with its own ink); Clean keeps its marks one neutral grey. It sits on the stage, not on a card, so a row's
   hover fill is a quiet step darker than the stage (owner, 18 Nov), reaching out round the row's mark and words */
.dm-ssx{display:flex;flex-direction:column;gap:10px;align-items:flex-start;--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.dm-ssx-pill{display:inline-flex;align-items:center;gap:var(--dm-s-2);height:30px;padding:0 10px 0 6px;border-radius:var(--dm-r-pill);background:var(--dm-chip);font-size:12.5px;color:var(--dm-fg2);transition:background .25s,color .25s}
@media (hover:hover) and (pointer:fine){.dm-ssx-pill:hover{background:var(--dm-hover);color:var(--dm-fg)}}
.dm-ssx-pill>svg{transition:transform .4s var(--dm-ease)}
.dm-ssx-pill[aria-expanded="true"]>svg{transform:rotate(180deg)}
.dm-ssx-ics{display:flex;gap:2px}
.dm-ssx-ics span{width:18px;height:18px;border-radius:50%;display:grid;place-items:center;font-size:9px;font-weight:500;color:#fff}
.dm-ssx-box{width:100%}
.dm-ssx-in{padding:2px 0 var(--dm-s-1);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.dm-ssx-fl{display:flex;gap:var(--dm-s-2);flex-wrap:wrap}
/* the filters are white chips with a dimmed grey edge; the picked one's edge is a step stronger */
.dm-ssx-fl .dm-chip{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent)}
@media (hover:hover) and (pointer:fine){.dm-ssx-fl .dm-chip:hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-faint) 50%,transparent)}}
.dm-ssx-list{display:flex;flex-direction:column;gap:2px;margin-inline:-6px}
.dm-ssx-s{display:flex;align-items:center;gap:10px;padding:7px 6px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;transition:background .25s}
@media (hover:hover) and (pointer:fine){.dm-ssx-s:hover{background:var(--dm-row)}}
.dm-ssx-s .dm-fv{width:22px;height:22px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;font-size:9.5px;font-weight:500;color:#fff;flex:none}
.dm-ssx-s .dm-t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-ssx-s .dm-h{font-size:12px;color:var(--dm-muted)}
.dm-ssx-s .dm-rel{width:36px;height:4px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-line);overflow:hidden;flex:none}
.dm-ssx-s .dm-rel i{display:block;height:100%;background:var(--dm-accent-mark,var(--dm-accent));border-radius:var(--dm-r-tiny,2px);transform-origin:left;animation:dm-ssrel .8s var(--dm-ease) both}
@keyframes dm-ssrel{from{transform:scaleX(0)}}
.dm-ssx-s .dm-ib{width:24px;height:24px;opacity:0;transition:opacity .2s}
@media (hover:hover) and (pointer:fine){.dm-ssx-s:hover .dm-ib{opacity:1}}
.dm-ssx-s .dm-ib:focus-visible{opacity:1}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-ssx :is(.dm-ib,.dm-pill):active,:root[data-style="clean"] .dm-ssx .dm-ib:active,:root [data-style="clean"] .dm-ssx .dm-ib:active,:root [data-style="clean"].dm-ssx .dm-ib:active{transform:none}
/* Clean (owner, 18 Nov): the sources' marks are one neutral grey with a hairline, not a colour each */
:root[data-style="clean"] :is(.dm-ssx-ics span,.dm-ssx-s .dm-fv),:root [data-style="clean"] :is(.dm-ssx-ics span,.dm-ssx-s .dm-fv),:root [data-style="clean"]:is(.dm-ssx-ics span,.dm-ssx-s .dm-fv){background:var(--dm-chip)!important;color:var(--dm-fg2)!important;box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .dm-ssx-s,:root [data-style="clean"] .dm-ssx-s,:root [data-style="clean"].dm-ssx-s{border-radius:var(--dm-r-in)}
/* the filter chips keep their quiet edge: the one hover fills them, and the picked one has the stronger fill (owner, 21 Nov:
   never a stronger edge); the sources pill deepens by the same fill, and holds the stronger one while its list is open
   (Agent harness keeps its own) */
:root[data-style="clean"] .dm-ssx-fl .dm-chip,:root [data-style="clean"] .dm-ssx-fl .dm-chip,:root [data-style="clean"].dm-ssx-fl .dm-chip{transition:background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-ssx-fl .dm-chip:not(.dm-on):hover,:root [data-style="clean"] .dm-ssx-fl .dm-chip:not(.dm-on):hover,:root [data-style="clean"].dm-ssx-fl .dm-chip:not(.dm-on):hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),inset 0 0 0 99px var(--dm-row)}}
:root[data-style="clean"] .dm-ssx-fl .dm-chip.dm-on,:root [data-style="clean"] .dm-ssx-fl .dm-chip.dm-on,:root [data-style="clean"].dm-ssx-fl .dm-chip.dm-on{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),inset 0 0 0 99px var(--dm-row-on)}
:root[data-style="clean"] .dm-ssx-pill:not(.dm-ahx *),:root [data-style="clean"] .dm-ssx-pill:not(.dm-ahx *),:root [data-style="clean"].dm-ssx-pill:not(.dm-ahx *){box-shadow:inset 0 0 0 99px transparent}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-ssx-pill:not(.dm-ahx *):hover,:root [data-style="clean"] .dm-ssx-pill:not(.dm-ahx *):hover,:root [data-style="clean"].dm-ssx-pill:not(.dm-ahx *):hover{background:var(--dm-chip);box-shadow:inset 0 0 0 99px var(--dm-row)}}
:root[data-style="clean"] .dm-ssx-pill:not(.dm-ahx *)[aria-expanded="true"],:root [data-style="clean"] .dm-ssx-pill:not(.dm-ahx *)[aria-expanded="true"],:root [data-style="clean"].dm-ssx-pill:not(.dm-ahx *)[aria-expanded="true"]{box-shadow:inset 0 0 0 99px var(--dm-row-on)}
:root[data-style="clean"] :is(.dm-ssx-pill,.dm-ssx-s,.dm-ssx-s .dm-ib),:root [data-style="clean"] :is(.dm-ssx-pill,.dm-ssx-s,.dm-ssx-s .dm-ib),:root [data-style="clean"]:is(.dm-ssx-pill,.dm-ssx-s,.dm-ssx-s .dm-ib){transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease)}

